source_text:
\spheader 132Yf\dvAnew{2010} Let $(X,\Sigma,\mu)$ be a measure space.   
Show that
$\mu^*:\Cal PX\to[0,\infty]$ is {\bf alternating of all orders}, that is, 

\Centerline{$\sum_{J\subseteq I,\#(J)\text{ is even}}
   \mu^*(A\cup\bigcup_{i\in J}A_i)
\le\sum_{J\subseteq I,\#(J)\text{ is odd}}\mu^*(A\cup\bigcup_{i\in J}A_i)$}

\noindent whenever $I$ is a
non-empty finite set, $\familyiI{A_i}$ is a family of
subsets of $X$ and $A$ is another subset of $X$.   
%mt13bits

}%end of exercises

\endnotes{

target_text:
\spheader 132Yf\dvAnew{2010} Misalkan $(X,\Sigma,\mu)$ suatu ruang ukur.
Tunjukkan bahwa $\mu^*: \Cal PX\to[0,\infty]$ {\bf alternating
(selang-seling) untuk semua orde}, yaitu,

\Centerline{$\sum_{J\subseteq I,\#(J)\text{ genap}}
   \mu^*(A\cup\bigcup_{i\in J}A_i)
\le\sum_{J\subseteq I,\#(J)\text{ ganjil}}
\mu^*(A\cup\bigcup_{i\in J}A_i)$}

\noindent kapan pun $I$ adalah himpunan berhingga tak-kosong,
$\familyiI{A_i}$ suatu keluarga subhimpunan-subhimpunan $X$, dan $A$ suatu
subhimpunan lain dari $X$.
%mt13bits

}%end of exercises

\endnotes{
